D.Strings[207036]="这些烈日行者太烦人了。我需要的是真正流着部落热血，心怀部落荣耀的士兵，而不是一些崇拜太阳的和平主义渣滓。$b$b联盟也来到了这里，$N。他们可能是跟踪我们过来的，也可能是得到了和莱莎一样的预见。这就不用管了。但我不想让他们知道我们目前的分歧有多么严重。趁他们的斥候还没有回去报告，先去南边杀掉那些探子吧。$b$b地狱咆哮之眼注视着你。"
D.Strings[207037]="莱莎已经客死异乡，我现在必须以活着的人为重。$b$b科尔率领一队斥候深入进西边的丛林。$b$b我也派出了斥候去调查朱鹤寺。拜托了，$N，帮我找到那些斥候，拿到他们的情报，然后跟科尔碰头并尽可能地帮助他。$b$b我们会尽快赶上你们的。"
