D.Strings[207044]="追踪事件：第1名"
D.Strings[207045]="追踪事件：第2名"
D.Strings[207046]="追踪事件：第3名"
D.Strings[207047]="追踪事件：第4名"
D.Strings[207048]="追踪事件：第5名"
D.Strings[207049]="追踪事件：第6名"
D.Strings[207050]="魔古族就是群恶棍，他们一直就是群恶棍。只有在传说中的魔古帝国时期，他们才会使用一些魔法。$b$b但这些魔古族竟然会用奥术传送门和法术，我们必须制止他们！$b$b$N，去找出魔古族用来施展魔法的所有神器，我看到很多收集者和复国者在西北边收集这种东西。"
D.Strings[207051]="煞魔拥有神秘的力量，他们能使受害者产生强烈的情绪波动，直至崩溃。$B$B当我们从寺院逃离的时候，鹤翼的高手们奉命断后掩护我们。毫无疑问他们会遭受到巨大的精神冲击，而我担心他们还不够坚强，迟早会陷入绝望。$B$B$N，我们必须向他们证明一切还有希望！向他们证明绝望也是可以被打败的！"
D.Strings[207052]="“精钢之躯，溃于灰心——绝望总源于内心。”$B$B这是朱鹤在煞魔爆发前夕，给我上的最后一课。现在看来，这句话说得丝毫不差……$B$B$N，煞魔就是首先从寺院的地窖内发动攻击的……$B$B他的所有教诲，朱鹤之道……都是为了应对惘之煞而存在的。$B$B几个世纪以来，朱鹤一直在蓄势等待此战！"
D.Strings[207053]="一直徘徊在朱鹤寺的地下室中。"
D.Strings[207054]="他的声音在你的脑海里萦绕。"
D.Strings[207055]="杀死指定的魔古杂种首领（对两个首领使用战士任务）"
D.Strings[207056]="去锦绣谷的郭莱遗迹找莱文·黎明之刃。"
D.Strings[207057]="我其实不知道他的名字是什么——他们的传法酋长经常都会换人。"
D.Strings[207058]="你要明白“刀耕”的真正含义，邻居。"
D.Strings[207059]="昆森狩猎酋长虽然都很勇敢，但通常都会摔下摩天山脊的悬崖。"
D.Strings[207060]="行动指挥官兼“加尔鲁什之拳”飞艇的船长。"
D.Strings[207061]="你与牧师之间建立了精神通道。"
D.Strings[207062]="你心中充满了紧迫感。"
D.Strings[207063]="隐秘大师恐怕得等一等了。看看那些人，$N。$b$B瘦得只剩下皮包骨了！他们一定是饿坏了。$b$B知道我们需要什么吗？一大碗热气腾腾的飞掠杂碎汤。$b$B在你经过附近的河流时，请收集一些完整的飞掠者腺体来，我可以用它们做一顿大餐。"
D.Strings[207064]="当时我们正在搜索南边的废墟，不知从哪儿突然冒出一群魔古族袭击了我们。$b$B我们中的一部分人好不容易突围撤回了营地，但大部分都被抓了。魔古族还抓了许多碰巧经过那里的部落人。$b$b求求你，$N，尽量多救出一些我们的哨兵。$b$b让那些逐晨者见鬼去吧。"
D.Strings[207065]="魔古族是不会使用奥术魔法的。$b$b他们就是群恶棍，他们一直就是群恶棍。只有在传说中的魔古帝国时期，他们才会使用一些魔法。$b$b但这些魔古族竟然会用奥术传送门和古代神器，我们必须制止他们！$b$b$N，去找出魔古族用来施展魔法的所有神器，我看到在南面的科夏废墟附近有很多这样的东西。"
D.Strings[207066]="帮帮我，$N。这些可怜的熊猫人需要治疗，但我的力量已所剩无几。$b$b我在自己的藏书中找到一本古籍，上面记载了如何将你之前采集的草药制成药膏。$b$b把这种药膏涂到受伤的熊猫人身上，应该能让他们重新站起来。"
D.Strings[207067]="他们抓走了我的女儿！勃罗耶……那个复国领主！我能透过丽娅拉的眼睛清楚地看到他的身影。$b$b那个傻姑娘一定是想凭一己之力把他干掉。$b$b拜托了，$N！快去科夏废墟把她救出来。$b$b我会找康一起试着吸引勃罗耶的注意力，把他从废墟里引出来。"
D.Strings[207068]="追踪事件：琪琪是名雇农"
D.Strings[207069]="追踪事件：艾拉是名雇农"
D.Strings[207070]="追踪事件：阿烁是名雇农"
D.Strings[207071]="追踪事件：老农山掌是名雇农"
D.Strings[207072]="追踪事件：郝瀚·泥爪是名雇农"
D.Strings[207073]="追踪事件：农夫老方是名雇农"
D.Strings[207074]="追踪事件：迪娜·泥爪是名雇农"
D.Strings[207075]="追踪事件：玉儿·采苇是名雇农"
D.Strings[207076]="追踪事件：醉鬼贾古是名雇农"
D.Strings[207077]="追踪事件：吉娜·泥爪是名雇农"
D.Strings[207078]="影踪派可能正在潘达利亚的其他地方处理着类似的冲突。$B$B快去四风谷西部边陲的石犁村找影踪派指挥官麦龙吧。告诉他，我们已经控制了这里的局势；不需要影踪派再派援兵来了。$B$B事实上，正相反——我会派出许多前来朝拜的追随者，给有需要的人们带去希望的消息。$B$B再次感谢你，$N。再见。"
D.Strings[207079]="我的小丽娅拉，她就是太任性了。我早应该知道她会去挑战复国领主的。$b$b自从她母亲去世后，我牺牲了本该陪她的时间，一心扑在寻找长生不老药上，坚信着我们父女凭着这个就能永远在一起。$b$b现在看来，是我的执念让我的小丽娅拉付出了生命代价。$b$b帮帮我，$N，当她醒来的时候，告诉她我爱她。"
D.Strings[207080]="滨岸村野牛人入侵追踪事件"
D.Strings[207081]="熊猫人联盟后续任务"
D.Strings[207082]="熊猫人部落后续任务"
D.Strings[207083]="去击败10个野牛人，把他引出来，然后干掉他！"
D.Strings[207084]="她还真是衣食无缺啊！"
D.Strings[207085]="曼说猢狲的嘴巴很脏。可在我看来还是挺干净的……"
D.Strings[207086]="我可不想像她那样住在山里。"
D.Strings[207087]="哈哈！她居然叫玉儿。"
D.Strings[207088]="我大老远就听见她的肚子叫得震天响了！"
D.Strings[207089]="诺米说他连小孩子都吃。"
D.Strings[207090]="那位老人家肯定很喜欢小鸡。"
D.Strings[207091]="如果我想成为农夫，就一定要跟他搞好关系！"
D.Strings[207092]="他呼出的空气闻着很像我叔叔。"
D.Strings[207093]="贾古"
D.Strings[207094]="我觉得她又善良又美丽。你可千万别告诉她这是我说的！"
D.Strings[207095]="到恆春谷的雙子碑找倫·火舌。"
D.Strings[207096]="青龙定相地形追踪"
D.Strings[207097]="海军上将泰勒正在等你回去。"
D.Strings[207098]="纳兹戈林将军正在等你归队。"
D.Strings[207099]="厄尔巴塔尔，野牛人勇士"
D.Strings[207100]="昆森猢狲的首领。"
D.Strings[207101]="追踪事件：开始初步扩张"
D.Strings[207102]="追踪事件：完成初步扩张"
D.Strings[207103]="追踪事件：开始第二步扩张"
D.Strings[207104]="追踪事件：完成第二步扩张"
D.Strings[207105]="追踪事件：和农场的狗谈一谈"
D.Strings[207106]="追踪事件：开始第三步扩张"
D.Strings[207107]="追踪事件：完成第三步扩张"
D.Strings[207108]="作为凶猛的丛林战士，蜥蜴人可不是那么好对付的。"
D.Strings[207109]="在你离开的这段时间，有一群土地精来到了粗麻小径。是我的堂弟牦牛鞋带着他们来的。$b$b但是他们遭到了肘锤猢狲的袭击。他们把我的堂弟和他的族人抓到北边去了。$b$b请你帮帮我，$N！救救我的堂弟。虽然他总是霉运不断，但他毕竟是我的堂弟啊。去银背堡垒前面的祭坛找他。"
D.Strings[207110]="山地部族的首领。"
D.Strings[207111]="要捕这种鱼，用钩子是不行的。"
D.Strings[207112]="魔古岬麻烦的真正源头……"
D.Strings[207113]="韶天魔古族的首领。"
D.Strings[207114]="追踪任务：开启金色谷入口"
D.Strings[207115]="小心，这些尖刺会留下讨厌的伤疤！"
D.Strings[207116]="他失去了防护盾的保护！"
D.Strings[207117]="即使是野兽也需要慈悲。"
D.Strings[207118]="钳爪正在大肆破坏当地的鲍鱼种群。"
D.Strings[207119]="標示－赤吉搖籃進程01"
D.Strings[207120]="標示－赤吉搖籃進程02"
D.Strings[207121]="標示－赤吉搖籃進程03"
D.Strings[207122]="標示－赤吉搖籃進程04"
D.Strings[207123]="你的第一个挑战者。"
D.Strings[207124]="你的下一个挑战者。"
D.Strings[207125]="她要求重赛！"
D.Strings[207126]="他的名字叫肥龙。“肥”就是他最好的写照。"
D.Strings[207127]="潘达利亚的新访客。"
D.Strings[207128]="一个力量惊人的超级战士，但伊兹沙好像很内向。"
D.Strings[207129]="这是你第一次和师父同场竞技！"
D.Strings[207130]="艾黎亚回来了，她决心要打败自己的“死敌”。"
D.Strings[207131]="前十场比赛中，他一场未败。"
D.Strings[207132]="他是从北面农场迁过来的移民。"
D.Strings[207133]="米德尔跟你一样，从未尝过失败的滋味。"
D.Strings[207134]="燕在这个岛上已生活了数十载。战斗就是他的生命。"
D.Strings[207135]="迷一般的战士回来了。"
D.Strings[207136]="塞隆尼斯的武艺超群、无人能敌。"
D.Strings[207137]="你的“死敌”回来了。"
D.Strings[207138]="寇塔峰大魔王"
D.Strings[207139]="这些发光的小虫子可以在卡桑琅丛林的树根上找到。"
D.Strings[207140]="日光爬行者"
D.Strings[207141]="解除恨之煞对他的控制！"
D.Strings[207142]="祝踏岚，影踪派掌门"
D.Strings[207143]="从胡墨戈斯那里夺回陈大师的旗帜和荣耀！"
D.Strings[207144]="奥苏尔野牛人的首领。击败他！"
D.Strings[207145]="奥苏尔部落里强大的迷雾萨满。"
D.Strings[207146]="奥苏尔迷雾萨满的首领。"
D.Strings[207147]="迦赫什，奥苏尔氏族"
D.Strings[207148]="比起穆山兽的力量，他更喜欢牦牛的灵活。"
D.Strings[207149]="黑鬃雇佣兵的指挥官。"
D.Strings[207150]="谢谢你能过来，$N。请原谅我故作神秘，但我不能冒险惊动魔古族，让他们知道我在这里的工作。$B$B他们正在谷里找寻某些东西。他们盗掘历代国王的陵寝，搜寻能够获得力量的圣物。$B$B我没能观察太久，否则就被发现了，不过我还是找到了一件宝贝。$B$B巴匈之舌能让我们进行远距离的安全通话，不过我得先把它跟自己绑定起来。$B$B如果你准备好了，我随时可以开始。"
D.Strings[207151]="拉博追踪任务"
D.Strings[207152]="腐化墨鳃锦鱼人的罪魁祸首。如果我们想救其他锦鱼人，就必须杀了他。"
D.Strings[207153]="刚晋升为酒仙的她，酿出的酒苦得要命。"
D.Strings[207154]="这位著名的武僧在潘达利亚动荡之时负责保护潘达利亚的大小道路，使其不受侵扰。"
D.Strings[207155]="街头霸王"
D.Strings[207156]="他们俩还是水火不容。"
D.Strings[207157]="聪明的阿西约和肯肯"
D.Strings[207158]="棘杖家族长期占据着比赛的冠军宝座。"
D.Strings[207159]="他从不摘下面具。"
D.Strings[207160]="一个耍炸药的武僧。"
D.Strings[207161]="黎明之花镇长"
D.Strings[207162]="他们每一个都有自己的看家本领。"
D.Strings[207163]="哈吉斯、希利斯和坦齐斯。"
D.Strings[207164]="[PH]殺!"
D.Strings[207165]="新手查布斯"
D.Strings[207166]="螳螂妖像使用武器一样使用煞的力量？这怎么可能？"
D.Strings[207167]="我们在你附近的位置发现了一位英杰。"
D.Strings[207168]="亲爱的$N，$b$b我们在锦绣谷中发现了一些惊人的东西。一座尘封的宝库，里面藏满了各种书籍、卷轴和知识，其历史可追溯到魔古帝国时期。$b$b请尽快来见我们。你可以先到声名狼藉的魔古山宝库，然后飞到宝库入口上方的平台，在这里你就可以找到这座闻道之座。$b$b期待你的到来！$b$b此致，$b$b游学者周卓"
D.Strings[207169]="亲爱的$N，$b$b我们收到了你关于土地精的调查报告，并确信我们已对他们的起源和历史有了明确的认识。$b$b如果你能来闻道之座一趟，我们就可以将这一成果加入你的私人收藏。$b$b感谢你的努力！$b$b此致，$b$b游学者周卓"
D.Strings[207170]="选择火法师"
D.Strings[207171]="选择冰法师"
D.Strings[207172]="选择牧师"
D.Strings[207173]="跟踪事件：已开始影踪派日常任务"
D.Strings[207174]="解锁雅丽亚·圣言者"
D.Strings[207175]="亲爱的$N，$b$b我们收到了你关于蜥蜴人的调查报告，并确信我们已经拼凑出蜥蜴人历史的线索。$b$b如果你能来闻道之座一趟，我们就可以将这一成果加入你的私人收藏。$b$b感谢你的努力！$b$b此致，$b$b游学者周卓"
D.Strings[207176]="一只坏螳螂。"
D.Strings[207177]="亲爱的$N，$b$b你那份关于猢狲的调查报告极富启发性。$b$b如果你能来锦绣谷的闻道之座一趟，我们就可以将这一成果加入你的私人收藏。$b$b感谢你的努力！$b$b此致，$b$b游学者周卓"
D.Strings[207178]="亲爱的$N，$b$b我已彻底研读了你那份关于锦鱼人的调查报告。这是一个神奇，并且十分聪明的种族。$b$b如果你能来闻道之座一趟，我们就可以将这一成果加入你的私人收藏。$b$b感谢你的努力！$b$b此致，$b$b游学者周卓"
D.Strings[207179]="亲爱的$N，$b$b我们一直都知道魔古族十分邪恶凶狠，而你的调查报告则表明他们比想象中更糟糕。$b$b如果你能来闻道之座一趟，我们就可以将这一成果加入你的私人收藏。$b$b感谢你的努力！$b$b此致，$b$b游学者周卓"
D.Strings[207180]="亲爱的$N，$b$b你打听到了我们的人民如何从魔古帝国手中赢得自由的故事。$b$b如果你能来闻道之座一趟，我们就可以将这一成果加入你的私人收藏。$b$b感谢你的努力！$b$b此致，$b$b游学者周卓"
D.Strings[207181]="亲爱的$N，$b$b我们非常感谢你在调查潘达利亚的传说一事上做出的努力，你寄给我们的关于螳螂妖的文件令我好几夜都无法安睡，真是可怕的故事。$b$b如果你能来闻道之座一趟，我们就可以将这一成果加入你的私人收藏。$b$b感谢你的努力！$b$b此致，$b$b游学者周卓"
D.Strings[207182]="亲爱的$N，$b$b我们已经将你所发现的有关云端翔龙骑士团的传说整理成了一个精彩的故事。$b$b如果你能来闻道之座一趟，我们就可以将这一成果加入你的私人收藏。$b$b感谢你的努力！$b$b此致，$b$b游学者周卓"
D.Strings[207183]="亲爱的$N，$b$b你关于卡拉克西的发现令我们非常震惊。$b$b如果你能来闻道之座一趟，我们就可以将这一成果加入你的私人收藏。$b$b感谢你的努力！$b$b此致，$b$b游学者周卓"
D.Strings[207184]="亲爱的$N，$b$b你那份关于野牛人的调查报告极富见地。$b$b如果你能来闻道之座一趟，我们就可以将这一成果加入你的私人收藏。$b$b感谢你的努力！$b$b此致，$b$b游学者周卓"
D.Strings[207185]="亲爱的$N，$b$b你那份关于酒中仙的调查报告非常……令人垂涎。$b$b如果你能来闻道之座一趟，我们就可以将这一成果加入你的私人收藏。$b$b感谢你的努力！$b$b此致，$b$b游学者周卓"
D.Strings[207186]="亲爱的$N，$b$b看上去好像你发现了少昊的所有故事，他是潘达利亚王朝的末代皇帝。$b$b如果你能来锦绣谷的闻道之座一趟，我们就可以将这一成果加入你的私人收藏。$b$b感谢你的努力！$b$b此致，$b$b游学者周卓"
D.Strings[207187]="亲爱的$N，$b$b多亏了你的调查，我们得到了全本的《刘浪之歌》。$b$b如果你能来锦绣谷的闻道之座一趟，我们就可以将这一成果加入你的私人收藏。$b$b感谢你的努力！$b$b此致，$b$b游学者周卓"
D.Strings[207188]="FLAG－解放漢恩"
D.Strings[207189]="螳螂高原的野牛人中堕落的死语者。"
D.Strings[207190]="铠胄野牛人的战争使者。"
D.Strings[207191]="选择防护战士"
