D.Strings[207195]="解锁老陈"
D.Strings[207196]="看来你是个不错的战士，$N。\n\n超风听说你的事迹之后，就一直念叨着要怎样踢爆你的……\n\n嗯，我觉得你应该挑战她一下，赢得她的尊重。"
D.Strings[207197]="体格强健（又喜欢夸夸其谈）的影踪派黑衣卫。"
D.Strings[207198]="$N！看你远道而来，却如此神采奕奕，真让我高兴。看来我俩所走的道路交集真多。$b$b我来这儿寻找我的家人。我听说有几个风暴烈酒家的人越过了长城，来帮忙抗击螳螂妖了。我想找到并加入他们。$b$b你在这儿见过叫风暴烈酒的人吗？你能帮我四处打听一下吗？"
D.Strings[207199]="阿宝在北郡修道院的武器大厅中，他站在治安官玛克布莱德的身后。"
D.Strings[207200]="好吧，$N，我还有一份工作要交给你。$B$B你看到那头关在围栏里的海狮了吗？他的名字叫狗狗。他是闷水壶多年以来的宠物。$B$B狗狗最近有些闹情绪——我想是关在围栏里让他不开心了。你应该去找闷水壶谈谈，告诉他这件事。$B$B我觉得，现在也是时候让你去见船长了。"
D.Strings[207201]="还有更大的威胁在等着我们。"
D.Strings[207202]="教训坏蛋"
D.Strings[207203]="到这里时，我们还应该做一件事。\n\n瑟拉提克统群者负责从空中指挥螳螂妖部队。如果我们让它活着，就会给守备部队带来麻烦。\n\n所以我们不会让它活着。除掉它，$N。"
