D.Strings[207243]="你和船长所做的一些事情让人惊叹不已，$N！能够得到你的加盟，真是万分荣幸。$B$B哦！句连活下来了！就在你用鱼叉捕鱼的时候，他游到了岸边。他正在兴高采烈地向人介绍某种巨型的蛋或随着狡一起被冲到岸边的东西。$B$B你愿意去他那里看一下吗？他现在可能已经把那个东西弄出水面了。"
