D.Strings[207366]="回锦绣谷的鎏金亭找安济·秋光。"
D.Strings[207367]="[殺死巨大蛟龍]"
D.Strings[207368]="[滅火]"
D.Strings[207369]="我们需要附近村落的帮助，这点很有必要，$N。$b$b我们需要村子来重整部队、治疗伤员。$b$b或许在目睹联盟的暴行后，村民们会加入我们。$b$b你将作为我们部落的使节，确保他们的村长会乖乖合作。别让我失望！"
D.Strings[207370]="整个铁腕机坪都听命于多伦上尉的指挥。给我拿下他！"
D.Strings[207371]="追踪任务：开启金色谷入口II"
D.Strings[207372]="去挑战祖塔来证明一下你的实力吧！"
D.Strings[207373]="把他逼到绝境！"
D.Strings[207374]="追踪事件：联盟炮艇的离开"
D.Strings[207375]="无与伦比！"
D.Strings[207376]="你有着光明的前景！"
D.Strings[207377]="愿你的道路正确如一。"
D.Strings[207378]="让他看看你的实力！"
D.Strings[207379]="让女妖之王以你为傲吧！"
D.Strings[207380]="让我们的人民以你为傲吧。"
D.Strings[207381]="快踏上新的旅程吧！"
D.Strings[207382]="去扫平他们吧，勇士！"
D.Strings[207383]="哇！你真了不起。"
D.Strings[207384]="你以为自己很了不起？"
D.Strings[207385]="哇！你真是太了不起了。"
D.Strings[207386]="我始终对你信心满满。"
D.Strings[207387]="你的胜利将在这里终结！"
D.Strings[207388]="你在成功道路上又迈出了一大步！"
D.Strings[207389]="祝你在战场上能载誉而归。"
D.Strings[207390]="你的另一段旅途又画上了一个完美的句号。"
D.Strings[207391]="全力应战！"
D.Strings[207392]="决不容许失败。"
D.Strings[207393]="最艰巨的挑战在等着你呢。"
D.Strings[207394]="即将结束！"
D.Strings[207395]="是时候面对我了。"
D.Strings[207396]="最终的挑战在等着你。"
