D.Strings[207403]="你已历经千辛万苦，决不能半途而废。"
D.Strings[207404]="准备好迎接下一场挑战了吗，驯宠师？"
D.Strings[207405]="優先級追蹤"
D.Strings[207406]="我等待着我们的对决。"
D.Strings[207407]="塞拉摩"
D.Strings[207408]="日常选择场景战役"
D.Strings[207409]="我想马上与你见面！"
D.Strings[207410]="期待与你会面。"
D.Strings[207411]="柯沃克追蹤[成長]"
D.Strings[207412]="返回卡拉克西维斯见证我族帝国的重生吧。"
D.Strings[207413]="每日防衛06"
D.Strings[207414]="我绝不允许兽人在这片土地上获得立锥之地。他们会污染这里，就如同他们在卡利姆多的所作所为。$b$b$N，我这儿正需要人手把部落送进坟墓。快到海岸上去，将联盟的怒火倾泻到他们的头上！$b$b干掉你见到的每一个兽人。让他们闻风丧胆！$b$b为了国王！"
D.Strings[207415]="欢迎你，$N！我听说过不少有关你的英勇事迹。我想请你帮忙测试一下我最新的“自动攻城器”，这可是一件具有可怕力量的多功能装置。$b$b我保证，它对使用者是绝对无害的。$b$b当你去统御岗哨时，请注意搜寻我的探查器。我先前已经派它们出去搜集攻击目标的情报。当你找到探查器时，就激活它，而我会把自动攻城器投放到你的位置。$b$b老规矩，我们战场见。"
D.Strings[207416]="说话声从某个隐蔽装置中传出。"
D.Strings[207417]="建造傳送門01"
D.Strings[207418]="消灭巨魔"
D.Strings[207419]="消灭魔古之魂"
D.Strings[207420]="魔古族派重兵把守矿脉的做法表明这是一处重要地点——可我们需要搜集更多有关他们活动的情报。因此我们派了一些密探去打探情报。\n\n不幸的是，许多人都被抓住了。我们发现其中有一些人正在矿脉中遭受折磨。你一定要救救他们——他们正在遭受非人的折磨……\n\n还有，救出他们之后，请你把抓获他们的人都干掉。不要对那些人手软，$N！"
D.Strings[207421]="殺死魔古首領取得鑰匙，使用後面的物品解謎@@@"
D.Strings[207422]="在12只啸天雏龙身边奔跑以惊吓它们。"
D.Strings[207423]="消灭游荡的巨魔战斗小队"
D.Strings[207424]="部落任務選擇:PvP"
D.Strings[207425]="部落任務選擇:PvE"
D.Strings[207426]="聯盟任務選擇:PvE"
D.Strings[207427]="聯盟任務選擇:PvP"
D.Strings[207428]="啊，$N，你正是我要找的$r。我又得到了一批战术魔法炸弹，需要将它们安放在位于东南边紫罗兰高地对面的关键位置。$b$b这些就交给你了。我不放心让我们的常规步兵接触如此强力的军火。噢……切勿在任何时候摇晃它们。$b$b在其中一艘肯瑞托舰船上安放一枚，在他们的补给品附近安放一枚，最后再在他们正在建造的构造体上安放一枚。"
D.Strings[207429]="$N？能找到你真是太走运了。$b$b陈·风暴烈酒让我把这个交给你，并要你去昆莱山的滨岸村见他。$b$b他遇见了你的一个朋友。不过那家伙能不能活下去就得看运气了。$b$b陈说，你可以让泰克泰克送你一程。"
D.Strings[207430]="木材收集追踪"
D.Strings[207431]="这块炉石是我和沃金在很久以前一次谈话中的一部分。$b$b他认为他的人民正处于危险之中。虽然我不知道在我离开的这段时间究竟出了什么事情，但至少这件事我是能为朋友做的。$b$b来吧，$N，跟我去回音群岛。我们必须确保暗矛部族的安全。"
D.Strings[207432]="有时候，打败一个传奇的唯一办法，就是和另一个传奇联手。"
D.Strings[207433]="啊，$N。酋长让我派你去银月城。$b$b他对洛瑟玛的研究进度很不满意，并认为你……对魔古族……的特殊认识或许会对他们有帮助。$b$b所以请你去一趟银月城，命令洛瑟玛加快研究速度。"
D.Strings[207434]="$N，瓦里安国王让我派你跟随他的儿子一起前往达拉然。他相信你能帮忙说服对方驱逐那里的血精灵。$b$b这些“夺日者”忠于部落，对我们的战局是个重大威胁。$b$b肯瑞托现在的领袖吉安娜·普罗德摩尔是我们自己人，要说服她赶走城市中的部落势力应该不难。$b$b你可以使用雄狮港的传送门前往紫色天台，并助安度因王子一臂之力。"
D.Strings[207435]="这名魔古刺客使用一种黑色的药膏，通过谐和的声率来杀戮他的敌人。"
D.Strings[207436]="在阿卡玛的手下死亡前击败恶魔"
D.Strings[207437]="$N！安度因王子不知怎么的又把他的警卫们给甩掉了。他对圣光的控制力正与日俱增。$b$b最后一次见到他的时候，他正前往昆莱山。他是在皇帝谷附近把我们的法师甩掉的。$b$b你能找找他吗？他坚持要去找那个所谓的能克制圣钟的东西。或许你可以在他控制你的心灵并让你一路手舞足蹈地跑回来之前，好好劝劝他。$B$B去和范妮谈谈，让她直接送你一程吧。"
D.Strings[207438]="灵魂之核"
D.Strings[207439]="昔日的秘密"
D.Strings[207440]="寇茹魔古的首领。活捉他！"
