D.Strings[207459]="我会把你变成蜥蜴人。"
D.Strings[207460]="欢迎到岛上来"
D.Strings[207461]="亲爱的$N，$b$b我已经读过了你关于赞达拉巨魔的报告，并确信我已经拼凑出他们近期进攻的线索。$b$b如果你能到锦绣谷的闻道之座来一趟，我们就可以将这一成果加入你的私人收藏。$b$b感谢你的努力！$b$b此致，$b$b游学者周卓"
D.Strings[207462]="亲爱的$N，$b$b滚雷的不详之音令我一代又一代的族人饱受困扰。正如你在自己研究中发现的那样，雷神正是那恐惧的源头所在。$b$b如果你能到锦绣谷的闻道之座来一趟，我们就可以将这一成果加入你的私人收藏。$b$b感谢你的努力！$b$b此致，$b$b游学者周卓"
D.Strings[207463]="亲爱的$N，$b$b魔古族当真与泰坦存在着某种关联吗？这简直太令人难以置信了。但在看过了你的研究报告后，关于魔古族的部分真相开始浮出水面。$b$b如果你能到锦绣谷的闻道之座来一趟，我们就可以将这一成果加入你的私人收藏。$b$b感谢你的努力！$b$b此致，$b$b游学者周卓"
D.Strings[207464]="打败那些寓言之兽！"
