D.Strings[207471]="啊，$N，你正是我要找的$r。我又得到了一批战术魔法炸弹，需要将它们安放在位于西北边寻晨者海角对面的关键位置。$b$b这些就交给你了。是时候让夺日者尝尝自己酿下的苦果。$b$b在其中一艘夺日者舰船上安放一枚，在他们的占卜水晶上安放一枚，最后再在通往他们前沿基地的桥梁上安放一枚。"
