D.Strings[207530]="这次注定不同"
D.Strings[207531]="德拉卡和德雷克塔尔正在前往先知岩。那是个神圣的地方，可是并不安全。可德拉卡坚称德雷克塔尔必须重建他与元素的联结。$b$b我能感觉到这片土地上的鬼魂变得焦躁不安。将要有事发生，这两个人肯定会需要帮助。$b$b拜托你了，$N，快去找他们，尽你所能提供帮助吧。他们的安全对我来说至关重要。"
D.Strings[207532]="她代表铁狼挥斥方遒。"
