D.Strings[207570]="啊，$N，很好。我需要派个外族人去和嘲颅氏族谈判。$b$b我们可以让他们帮忙带路，可他们跟戈尔隆德一样，既危险又难以预料。$b$b顺着这条路往前走，看看你能不能找到愿意与你交谈的人。$b$b也许他们能用全新的眼光审视你，并愿意等你开口说完话再动手。"
