D.Strings[207585]="我收到了一样奇怪的东西，还附了一张字条。你瞧瞧，好像是用你们的语言写的，指挥官。\n\n<亲爱的杜隆坦先生，\n\n我是佩妮……来自艾泽拉斯，你还记得吧？我们在$N的要塞有过一面之缘。\n\n总之，就像我跟你说的那样，我具备了五级黑锤的工程学资质，迫切希望能够为你效劳。越是危险，我就越喜欢！\n\n当你遇到麻烦时，发射这枚老旧的信号枪就行了，我会像闪电一般立即出现在你面前！\n\n祝一切顺利，\n\n佩妮>"
