D.Strings[207594]="在迪奥诺之劫消灭12个守卫者。"
D.Strings[207595]="你帮助了我，现在该换我帮你了，$N。你要找的花蕾就在附近的洞穴里，在这群虎人新头领的看管之下。$b$b去干掉他，然后把花蕾交给下方的古树。希望这样可以清除掉那些植物，好让我继续正常狩猎……"
