D.Strings[207644]="从技术上讲，他那把锤子应该是煤灰色。但没人有胆量指出这一点。"
D.Strings[207645]="技术上讲，他那把锤子应该是煤灰色。但没人有胆量指出这一点。"
D.Strings[207646]="这一定不是塞林卖给他们的。决不可能！他们肯定是把他关在这附近了。$B$B快来，$N。我知道他跟联盟在一起，而且我也明白你跟联盟是死对头，可我们都不愿意让他的作品落在钢铁部落的手里——相信我！"
