D.Strings[207691]="$N！我得到关于父亲下落的线索了。有人报告说在____看见他跟暗影议会的兽人们在一起。$b$b我父亲是位造诣极深的学者，有着渊博的古老学识。我真不敢想象暗影议会为了得到那些知识会对他做出什么事情来。$b$b你能去____吗？抓住他们的军官，看看他们都知道些什么？"
