D.Strings[207767]="你还记得我们的问候语吗，$N？$B$B“暗影蔽日，渡鸦吞天。”$B$B那不仅是一句古老的诗文——还是行动的召唤。老派的追随者们正在集结，而我必须加入他们。我想他们也需要你。$B$B沿着这条路前往乌鸦小屋。你会找到某个老太婆的家。用你跟我打招呼的方式去问候她，然后她会为你指明方向的。$B$B尽管你看不见我，可我就跟在你身后。"
D.Strings[207768]="你的第一个对手是碾槌！"
D.Strings[207769]="不被犁爪吃掉的秘诀，就是避开它的鸟喙！"
