D.Strings[207863]="在塞泰克山谷杀死6名塞泰克预言者和6名塞泰克选民。"
D.Strings[207864]="一位疯狂的奥术师，坚信自己是泰罗克转世。"
D.Strings[207865]="在塞泰克手中重生。"
D.Strings[207866]="从5名死亡的割颅者身上拿下面具。"
D.Strings[207867]="杀死7只真菌侦察者。"
D.Strings[207868]="其他人……都死了，或是游荡到浓雾深处去了。它同样也在召唤我，但我的意志足够强大。我选择杀死他们，直到我的身体被他们击垮。但我还没杀够，$N，还不够！去吧，去杀死他们，告诉我的猎队领袖，当走进黑暗时，我不是孤身一人。"
D.Strings[207869]="插曲：魔化硬木"
D.Strings[207870]="消灭8个受难残影。"
D.Strings[207871]="必须让高尔玛什·地狱咆哮的灵魂安息！"
D.Strings[207872]="从汽怒元素身上找到100个淬火之水。"
D.Strings[207873]="消灭6个覆菌蹒跚者。"
