D.Strings[207876]="从真菌践踏者身上收集3枚孢子囊，并把它们带给戈鲁科尔。"
D.Strings[207877]="我能感觉到在沼泽中存在一股强大的力量，$N。它在吸引着我。我们必须前去弄清真相。你先走一步吧，我得把这些蘑菇吃完。"
