D.Strings[207900]="情况不妙，$N。这些聪明的食人魔在这里设立了一座传送门，并不断把别处的食人魔带到这里来。$B$B不过要维持这座传送门似乎要花不少气力。假如你把它关上，或许可以拖延他们一段时间。"
