D.Strings[207973]="我能感觉到这沼泽中有一股强大力量，$N。它就离这不远。$B$B我要把这些恶心的东西吃完，你先帮我过去看看吧。我会跟上的……"
D.Strings[207974]="取得10件神秘的圣物。"
D.Strings[207975]="寶物：沉沒的漁船"
D.Strings[207976]="收集100份萨格雷徽记。"
D.Strings[207977]="获得5枚浸水的电池。"
D.Strings[207978]="插曲：魔法精靈龍"
D.Strings[207979]="插曲：巴潤"
D.Strings[207980]="插曲：真理"
D.Strings[207981]="使用泰罗克雕像重现泰罗克与血鬃虎人的战斗。消灭30名血鬃短齿战士、20名成年血鬃虎人，以及虎王卡拉什。"
D.Strings[207982]="从古树身上收集30份新鲜的木炭。"
D.Strings[207983]="青铜的胜利"
D.Strings[207984]="白银的胜利"
D.Strings[207985]="黄金的胜利"
D.Strings[207986]="$N？见到你真是太好了。$b$b我当时正想甩掉那个原祖荆兽，结果就闯到这个游侠营地里来了。$b$b还没等我反应过来，大地就开始震颤，不知打哪冒出来好多愤怒的植物。$b$b我好不容易才从坦克里爬出来，眼睁睁地看着那个原祖荆兽把坦克像空啤酒杯那样抛了出去。$b$b我得沿路返回，找找我的坦克。$b$b等你完成这里的任务后，我们到那见吧。"
D.Strings[207987]="消灭9个野性生长物。"
D.Strings[207988]="从履岩蜥蜴或腐烂的蜥蜴身上收集9份蜥蜴肉。"
D.Strings[207989]="设备"
D.Strings[207990]="消灭15个沼泽居民。"
D.Strings[207991]="使用泰罗克雕像重现泰罗克被贬落时的情形。找到蕾希，集结5名流亡者利爪卫士，消灭1名疯狂的流亡者，再使用安苏之眼。"
D.Strings[207992]="认真聆听泰罗克的贬落。"
D.Strings[207993]="与泰罗克之影交谈来获得他的力量。消灭25个碎手战士、4个碎手地穴主宰，然后面对卡加斯·刃拳。"
D.Strings[207994]="插曲：踐踏者克里格"
D.Strings[207995]="格里姆加，镇子里最厉害的家伙……之类的。"
D.Strings[207996]="毁灭者入侵？"
D.Strings[207997]="击败10名格罗姆卡步兵。"
D.Strings[207998]="血精灵耳朵"
D.Strings[207999]="地精鼻子"
D.Strings[208000]="牛头人的蹄子"
D.Strings[208001]="兽人的牙齿"
D.Strings[208002]="巨魔的脚"
D.Strings[208003]="熊猫人毛皮"
D.Strings[208004]="寶藏：亞魯梅爾的槌子"
D.Strings[208005]="消灭3个食人魔和3个独眼魔。"
D.Strings[208006]="从悬槌堡的怪物身上收集125块消魔之石。你要塞的追随者们或许也能在某些特定的任务中找到石头。"
D.Strings[208007]="在过往一千多年的岁月里，食人魔巫师之王凭借各类神器维护着统御帝国的铁腕政权。受信任的副官们手中握有魔法宝石，可以在战场上行使帝王的意志。这些“消魔之石”直到今天仍然力量不减，就散落在悬槌堡的各处。有时是数块成群。$b$b帮我找125块消魔之石来！"
D.Strings[208008]="收集3块元素石板。从黑石锻造厂的首领身上收集元素符文，把石板拼合起来。"
D.Strings[208009]="消灭4个碎手盲眼行者、3个碎手收割者和1个碎手吟血者。"
D.Strings[208010]="暗夜精灵的徽记"
D.Strings[208011]="矮人的脊骨"
D.Strings[208012]="一绺侏儒的头发"
D.Strings[208013]="德莱尼的尾巴"
D.Strings[208014]="人骨片"
D.Strings[208015]="收集毒刃的秘密配方和6个毒药桶。"
D.Strings[208016]="封印命运：荣誉"
D.Strings[208017]="钢化命运印记：军火"
D.Strings[208018]="时机到了，$N。\n\n从长眠中唤醒利爪之王。将他召唤到这个世界中来，帮忙消灭我们的敌人！"
D.Strings[208019]="钢化命运印记：埃匹希斯水晶"
D.Strings[208020]="消灭1名信徒和风卫士科雷克斯。与卡鲁交谈飞往啸风平台。"
D.Strings[208021]="飞回家"
D.Strings[208022]="插曲：Nas Dunberlin"
D.Strings[208023]="赶在其他竞争对手之前收集到4块影月皮革和3个银翼利爪，并回去交给法娜拉。"
D.Strings[208024]="主矿脉"
D.Strings[208025]="收集50块鲜血之石，并把它们交给巨魔仆从伍迪。"
D.Strings[208026]="这把锤子曾经是用来为我的霜狼兄弟姐妹们打造威风的武器。$B$B当我被雷神氏族抓为俘虏时，我拒绝使用它。我怎么能帮敌人铸造武器，让他们拿来对付我自己的族人呢？$B$B眼睁睁地看着这把锤子落到恶人手中，损坏得面目全非，我的内心感到非常难过。$B$B希望有一天，我能把它传给库格拉，可现在她却愤怒得连来坟墓祭拜我都不肯。$B$B拜托了，$N，你能帮我修好锤子，并向那些造成今日悲惨结局的人复仇吗？$B$B为了库格拉……"
D.Strings[208027]="$N，谢谢你为我报了仇……可我还要请你帮个忙。$B$B如果你能帮我做成这件事，我将永远不会忘记你的恩情。$B$B拿上这些东西，到岩牙岗哨的熔炉那找我。$B$B我将自己的一部分精华灌注到了这些东西里面，可我们还需要找别人帮忙来熔铸锤子。$B$B现在到了跟库格拉言归于好的时候了，只有那样我们两个才都能得到安宁……"
