D.Strings[208123]="遗物猎人激活"
D.Strings[208124]="地下城激活"
D.Strings[208125]="在秘密巢穴里消灭15名暗影议会成员。"
D.Strings[208126]="我的迦罗娜"
D.Strings[208127]="在蓝翼繁育地消灭12个枯法者。"
D.Strings[208128]="找到一个黯淡的魔网水晶，然后用它使1条法力枯竭的雏龙复苏。"
D.Strings[208129]="他一直从废墟上方对你进行骚扰。也许是时候去会会他了……"
D.Strings[208130]="宠物对战未激活"
D.Strings[208131]="影月氏族的战士，也是研究当地水晶的专家。"
D.Strings[208132]="符文大师，影月氏族的高阶仪祭师。"
D.Strings[208133]="选择与亡者为伴的神秘隐士。"
D.Strings[208134]="成为纳格兰鲜血竞技场的竞技场之王。"
D.Strings[208135]="在蓝翼栖地消灭15个枯法者。"
D.Strings[208136]="幸会，$N。我代表安度因·乌瑞恩国王欢迎你的到来。$B$B我的队伍正准备执行一项特殊的任务，而国王陛下希望你也能加入。请查阅这份皇家召令，如果没有异议的话，就请你随我一起返回暴风城港口。$B$B<罗杰斯递给你一份密封的信函。>"
D.Strings[208137]="收集5个天火急救包。"
D.Strings[208138]="消灭8个被遗忘者蝙蝠骑手或亡灵哨兵。"
D.Strings[208139]="很高兴看到你在空难中幸存了下来。不幸的是，大部分登船的敌人也活了下来。$B$B一想到那些怪物登上了我的船，我就直犯恶心。去干掉他们，$N。为了我的船员……为了乌瑞恩国王……$B$B为了联盟！"
D.Strings[208140]="第七军团的英雄们当时都留在了飞艇的前部迎战风暴幼龙，掩护船员撤离。$B$B但他们至今未归。$B$B请你去找到他们，$N！"
D.Strings[208141]="从静电力场中救出6名第七军团龙骑兵。"
D.Strings[208142]="唤醒8名利爪德鲁伊。"
D.Strings[208143]="不知为何，这个奇怪的维库老人好像很了解你……"
D.Strings[208144]="特德的主人-上上任"
D.Strings[208145]="乌瑞恩国王在等你。"
D.Strings[208146]="杀死6只被激怒的血魂。"
D.Strings[208147]="大量草药"
D.Strings[208148]="你好，$N。我代表希尔瓦娜斯·风行者欢迎你的到来。我想你应该对这个名字很熟悉。$B$B<纳萨诺斯将一封密函塞到你手里。>$B$B读完之后跟我走。$B$B你识字的吧？"
D.Strings[208149]="库伦肯定是在动身执行其他任务之前写了这份报告留给纳萨诺斯。"
D.Strings[208150]="从冥狱深渊的克瓦迪尔召雾者和掠魂者身上收集20片海草。"
D.Strings[208151]="把德拉诺错币交给铁炉堡的克罗姆·粗臂。"
D.Strings[208152]="把德拉诺错币交给幽暗城的艾斯特蕾·根德瑞。"
D.Strings[208153]="消灭10个变异熊或变异水手。"
D.Strings[208154]="消灭15个第七军团伞兵或天火号狮鹫骑士。"
D.Strings[208155]="守护玫瑰"
D.Strings[208156]="在你的要塞里找到克劳勒中士。"
D.Strings[208157]="杀死12名萨格雷。"
D.Strings[208158]="在你的要塞里找到格里姆加中士。"
D.Strings[208159]="在邪魂堡垒消灭40个恶魔。"
