D.Strings[208164]="杀掉12个复生的刺客、黑鸦猎隼或复生猎犬。"
D.Strings[208165]="收集30个腐化根茎样本。"
D.Strings[208166]="收集5片腐化花瓣。"
D.Strings[208167]="万能钥匙在他手上。"
D.Strings[208168]="拉文凯斯领主的副官。"
D.Strings[208169]="尽力阻止他。"
D.Strings[208170]="从她的尸体上拿到萨格里特钥石！"
D.Strings[208171]="燃烧军团的指挥官就在火山下方的低地里。将他的力量占为己有。"
D.Strings[208172]="使用罗诺斯的水晶矿锄对魔石进行35次开采。"
D.Strings[208173]="在月翼浅滩收集5枚失窃的月翼龙蛋。"
D.Strings[208174]="战机控制板"
D.Strings[208175]="解救7只被捕获的巨鹰。"
D.Strings[208176]="天角牛头人是举世闻名的探路者和猎手。$b$b他们是一个骄傲的部族，但应该听得进道理。$b$b如果觉得路途危险的话，至高岭任何一个飞行管理员都能带你飞去那儿。$b$b$N，请你去找到他们的领袖拉善，告诉他我们应该是团结一致的高岭部族。"
D.Strings[208177]="大元帅泰布雷德是联盟在阿什兰部队的领袖。"
D.Strings[208178]="沃拉斯是部落在阿什兰部队的领袖。"
D.Strings[208179]="查看发抖的灰喉熊崽"
D.Strings[208180]="获取10块夏多雷丝绸。你可以通过其他冒险者、拍卖行，或者破碎群岛的人形生物获取夏多雷丝绸。"
D.Strings[208181]="获取3条符文肠线。"
