D.Strings[208186]="在苏拉玛消灭25个枯法者。"
D.Strings[208187]="从地狱火堡垒的首领身上收集33本混沌魔典。"
D.Strings[208188]="在河湾消灭8个卓格巴尔。"
D.Strings[208189]="夺取他的精华并让自己变得更加强大。"
D.Strings[208190]="在干船坞与索洛格碰头。"
D.Strings[208191]="消灭8个暴怒的琥珀碎片。"
