D.Strings[208200]="务必带上一些隐形饮剂，以便进入她的房间。"
D.Strings[208201]="取得卡德加的银发，1份萨格拉斯之血，5份卡多雷姜酒，以及5份阿苏纳湿乳酪。"
D.Strings[208202]="引导小精灵穿过隐秘之池并种下1棵树木。"
D.Strings[208203]="从巫林女巫身上收集50片女巫之羽。"
D.Strings[208204]="在安瑟平原收集4块蓟鬃熊皮。"
D.Strings[208205]="返回你的船坞，并与梅里克会面。"
D.Strings[208206]="返回你的船坞，并与若洛什会面。"
D.Strings[208207]="所有的一切！"
D.Strings[208208]="在女巫秘地消灭8个紫喉鹰身人和6个天须死忠者。"
D.Strings[208209]="从塔纳安丛林的任意宝藏、稀有生物或稀有精英生物身上收集10枚被邪能腐蚀的埃匹希斯碎片。"
D.Strings[208210]="女巫秘地宝藏"
D.Strings[208211]="在黯石洞穴消灭8个鱼人。"
D.Strings[208212]="咕咕噜咕噜噜咕噜！噜咕咕咕！"
D.Strings[208213]="野性的复仇"
D.Strings[208214]="凤凰峰宝藏"
D.Strings[208215]="找回10个强能水晶。"
D.Strings[208216]="消灭7个卓格巴尔嗜魔者或凶猛的食岩元素。"
D.Strings[208217]="在大地母亲之赐杀掉10条生病的幼虫和3条过度生长的幼虫。"
D.Strings[208218]="松岩盆地宝藏"
D.Strings[208219]="获取他的力量，避免伊利达雷据点的部队遭受伏击。"
D.Strings[208220]="从泽斯高的血环氏族兽人身上收集25柄血环仪祭之刃。"
D.Strings[208221]="在铁城港的士兵身上收集15张钢铁部落海军机要。"
D.Strings[208222]="在塔纳安丛林的邪兽人身上收集20个魔血之瓶。"
D.Strings[208223]="从卡纳克废墟或基尔加丹王座的暗影议会代表身上搜集20封暗影议会密函。"
D.Strings[208224]="从塔纳安丛林的沙纳尔神殿后面的矿井中收集8块德拉诺水晶原石。"
D.Strings[208225]="在塔纳安丛林击杀20个恶魔。"
D.Strings[208226]="从塔纳安丛林的各种野生动物身上搜集100枚塔纳安丛林利齿。"
D.Strings[208227]="在塔纳安丛林击杀25名钢铁部落兽人。"
D.Strings[208228]="消灭10个邪能图腾牛头人。"
D.Strings[208229]="在塔纳安的雄狮岗哨找到守备官科索斯。"
D.Strings[208230]="在塔纳安的沃玛尔找到暗影猎手德恩加。"
D.Strings[208231]="把8条白水鲤鱼放回河里。"
D.Strings[208232]="抓住那些小东西！"
D.Strings[208233]="前往码头找到“老水手”乔伦。"
D.Strings[208234]="在干船坞与库隆克·锈火碰头。"
D.Strings[208235]="伊莫拉斯充斥着凝聚的纯粹邪能。"
D.Strings[208236]="他守卫着地窟出口。"
D.Strings[208237]="欢迎来到暴风城，这里是人类王国的心脏。不过，这座圣光之城现在被悲伤所笼罩。$b$b瓦里安·乌瑞恩国王战死沙场，留下了他的儿子安度因继承大统。$B$B联盟的领袖们在这里汇聚，祭奠英雄的离去。$b$b毫无疑问，你的特殊能力不可或缺。$b$b你可以在暴风要塞的王座厅找到新任国王，他身边有你的一位伊利达雷同伴。我得去达拉然一趟。$b$b祝你好运，$N。"
D.Strings[208238]="在铁角飞地附近收集金属废料，然后使用绿蹄的铁砧和熔炉制作废金护手、废金护掌、废金腕甲，以及1个废金护指。"
D.Strings[208239]="从黑鸦堡垒的精灵身上取得5件黑鸦胸甲。"
D.Strings[208240]="从苏拉玛的虫语爪牙身上取得10个邪能之核。完成以后，把它们交给达拉然的马修。"
D.Strings[208241]="消灭7个蓝烛盗墓贼。"
D.Strings[208242]="消灭10个巨石卓格巴尔。"
D.Strings[208243]="他拿着失窃的卡兹格罗斯之锤。"
D.Strings[208244]="地底之王达古尔"
D.Strings[208245]="一只让风暴峡湾的维库人惊恐万分的巨型蜥蜴。"
D.Strings[208246]="一只在裂风丘陵上空捕猎的巨鹰。"
D.Strings[208247]="在尤顿林地从健壮的高地符角牛身上收集8块多肉的麝牛肋排。"
D.Strings[208248]="苍穹圣墓宝藏"
D.Strings[208249]="胡恩之路宝藏"
D.Strings[208250]="白水溪宝藏"
D.Strings[208251]="白水溪宝藏\n"
D.Strings[208252]="大地母亲之赐宝藏"
D.Strings[208253]="生命之泉洞穴宝藏"
D.Strings[208254]="林荫瀑布宝藏"
D.Strings[208255]="猎血高地宝藏"
D.Strings[208256]="黯石岩洞宝藏"
D.Strings[208257]="女巫林地宝藏"
D.Strings[208258]="获取100个盲目之眼。"
D.Strings[208259]="巨石首领"
D.Strings[208260]="为伊尔蒂制作2张附魔戒指 - 全能真言卷轴。你可以从抄写员或拍卖行处获得羊皮纸。"
D.Strings[208261]="在伊利达雷哨所对6名恶魔猎手使用附魔羊皮纸。"
D.Strings[208262]="击败暴怒的琥珀碎片，收集8个琥珀碎片水晶，并交给雷霆图腾的古隆。"
D.Strings[208263]="在黑鸦堡垒消灭暗夜精灵，并收集他们的魔法渡鸦徽记。分解徽记，然后把8份渡鸦之尘交给娜拉米娅，作为你消灭他们的证据。"
D.Strings[208264]="这只凶猛的纳迦一路打拼，现在的头衔是深海指挥官。"
D.Strings[208265]="在邪焰隘口消灭恶魔。取得他们的邪壳符文并分解出5份邪污谎言之尘。完成以后回去找堕落的女祭司。"
D.Strings[208266]="取得20份玫红颜料和2份蜡黄颜料。颜料可以通过研磨草药获得。"
