D.Strings[208547]="收集10个盐目手镯。"
D.Strings[208548]="为10名女王的复仇号水手终结痛苦。"
D.Strings[208549]="在晨曦裂口寻找莉莉娅·晨风。"
D.Strings[208550]="英灵殿：熊王"
D.Strings[208551]="英灵殿：激动人心的挑战"
D.Strings[208552]="英灵殿：维瑟尔的礼物"
D.Strings[208553]="解救10名女王的复仇号水手。"
D.Strings[208554]="痴心妄想"
D.Strings[208555]="邪焰隘口的指挥官"
D.Strings[208556]="练习用魔杖击中10个魔杖目标。"
D.Strings[208557]="击败4个艾瑞达鞭魂者，救出他们手里的俘虏。"
D.Strings[208558]="黄金海湾的威胁。"
D.Strings[208559]="扭曲之魂"
D.Strings[208560]="捉住鬼祟的小鬼，找回魔典：奥术之道。"
D.Strings[208561]="找到3头惊恐的山地鹿，并把它们带回莉萨·驭风的兽栏里。"
D.Strings[208562]="懸賞：亞克維洛斯"
D.Strings[208563]="在雷霆图腾找到4面大型、4面中型、以及4面小型仪式用鼓。"
D.Strings[208564]="海盗恶霸"
D.Strings[208565]="消灭42个巫环攻击者。"
D.Strings[208566]="前往黑暗神殿与阿卡玛对峙。说服他加入你的队伍，一起对抗燃烧军团。"
D.Strings[208567]="指挥官，请尽快返回邪能之槌号。"
D.Strings[208568]="虽然他的样子是污染者拉瑟莱克，但实际是恶魔猎手洛拉姆斯·萨里比迪斯的灵魂在控制这个恐惧魔王……大多数时候是这样。"
D.Strings[208569]="取得3块积怨宝石。"
D.Strings[208570]="不朽法师"
D.Strings[208571]="黑心林地：米萨纳"
D.Strings[208572]="收集20株安瑟瑞尔花。"
D.Strings[208573]="收集1份抑魔金。你可以从达拉然魔法商业区的命运熔炉获得抑魔金，也可以在拍卖行购买。"
D.Strings[208574]="在《军团再临》地下城里收集15个优质灵魂。"
D.Strings[208575]="到风暴峡湾找到这个守望者。她之前朝蔑魔战争营地去了。"
D.Strings[208576]="除掉他，拿到他手里的符文。"
D.Strings[208577]="你需要他的邪能符文来使符文石失效。"
D.Strings[208578]="找到并消灭弗洛奇。拿走他的符文，这样你才可以救出玛拉丝。"
D.Strings[208579]="暗心灌木林：怒朽"
D.Strings[208580]="黑心林地：库德兹拉"
D.Strings[208581]="黑心林地：被维护的维护者"
D.Strings[208582]="艾萨拉之眼：恐惧终末"
D.Strings[208583]="在失落之光岩洞中杀掉10只枭兽和8只波动的骨质软泥怪。"
D.Strings[208584]="在失落之光岩洞援救6名月之姐妹。"
D.Strings[208585]="帮玛拉丝·夜影消灭这个邪能领主，然后她就会告诉你怎么取回萨格里特钥石。"
D.Strings[208586]="艾萨拉之眼：阿苏纳珍珠"
D.Strings[208587]="噬魂之喉：深海威胁"
D.Strings[208588]="群星庭院：机器里的鬼魂"
D.Strings[208589]="群星庭院：把眼镜带给我"
D.Strings[208590]="清除9个灵魂。"
D.Strings[208591]="沉睡腐蚀"
D.Strings[208592]="噬魂之喉：地狱之口"
D.Strings[208593]="眾星之廷：解除崗哨的武裝"
D.Strings[208594]="眾星之廷：欺詐學生"
D.Strings[208595]="噬魂之喉：巨兽归来"
D.Strings[208596]="通缉：巢母舒玛利斯"
D.Strings[208597]="危险：镰刀大师希尔拉曼"
D.Strings[208598]="危险：狂怒的奥格洛克"
D.Strings[208599]="口袋巫师"
D.Strings[208600]="在灰白原野中收集5个潮湿的刺肉果。"
D.Strings[208601]="危险：被侵蚀的崩岩"
D.Strings[208602]="劣魔头目。首席捣蛋鬼。暴力又难以捉摸。满嘴恶言。"
D.Strings[208603]="危险：野蛮的卡索尔"
D.Strings[208604]="在灰白原野杀掉8个怒目地劣魔。"
D.Strings[208605]="在灰白原野中使用老灰背的法杖摧毁5个纠缠的荆棘。"
D.Strings[208606]="激活传送门，并返回沙尔艾兰。"
D.Strings[208607]="随机英雄日常 （第一次）（军团再临）"
D.Strings[208608]="随机英雄日常 （第N次）（军团再临）"
