D.Strings[208615]="前往黑暗神殿与阿卡玛作战。说服他加入你的队伍，一起对抗燃烧军团。"
D.Strings[208616]="守望者地窟：启动序列"
D.Strings[208617]="守望者地窟：严峻的问题"
D.Strings[208618]="危险：玛丽桑德拉"
D.Strings[208619]="在苍白栖地击败折磨幼龙的穴居人，救出6只石龙。"
D.Strings[208620]="危险：缚魂者哈尔多拉"
D.Strings[208621]="危險：魯夫‧斷骨者"
D.Strings[208622]="危险：拉格萨"
D.Strings[208623]="危险：符文先知希格维德"
D.Strings[208624]="等你有了时间，就尽快返回暗影大厅。"
D.Strings[208625]="“孤狼”是来帮助我们解决问题的。他才智过人、魅力非凡，同时还散发出一丝可怕的杀气。"
D.Strings[208626]="“孤狼”温斯顿·沃尔菲"
D.Strings[208627]="危险：莫提法洛斯"
D.Strings[208628]="危险：饥渴的瓦拉卡"
D.Strings[208629]="危险：弗约顿"
D.Strings[208630]="危险：风暴之羽"
D.Strings[208631]="危险：低语者"
D.Strings[208632]="危险：伊墨利安"
D.Strings[208633]="危险：超级奥能金刚"
D.Strings[208634]="危险：巨大的玛伯布"
D.Strings[208635]="危險：萊瑟隆"
D.Strings[208636]="深渊魔王"
D.Strings[208637]="屠殺惡魔大軍"
D.Strings[208638]="枭兽的狂怒"
D.Strings[208639]="危险：被遗忘的妮拉西娅"
D.Strings[208640]="我们需要你的帮助！"
D.Strings[208641]="危险：尖啸先锋"
D.Strings[208642]="战争领主，虽然我们相处的时间尚短，但你已经为我们的议会做了太多的贡献。$b$b在你执著精神的激励下，我们找到了一种新的方法，它可以将翡翠梦境的力量赋予你的武器！$b$b一切都已就绪，只要你做好准备，我就可以开始。"
