D.Strings[208678]="战争领主，虽然我们相处的时日尚短，但你已经为议会做出了伟大的贡献。现在，光影祭坛已经改造完成，该轮到我们祝你一臂之力了。我们发现了一种方法，可以唤醒武器中的沉睡力量！$b$b请走到祭坛面前，并高举你的武器。"
