D.Strings[208690]="战争领主，你将白银之手骑士团重新团结为一个整体，从来没有哪个战争领主能做到这一点。你的行动向我们表明，在圣光的引领下，我们坚定的信仰可以战胜任何挑战。$b$b在你的激励下，我们的工匠奋发努力，力图强化远古君王祭坛。它将为你解放这把武器的真正力量。$b$b现在，他们的工作终于完成了！当你准备好之后，请走上前来，并与我们一同开始仪式。"
