D.Strings[208702]="通缉：伯格佐格"
D.Strings[208703]="通缉：地狱火领主"
D.Strings[208704]="通缉：末日领主卡兹洛克"
D.Strings[208705]="通缉：赛法努斯"
D.Strings[208706]="通缉：沃洛伦队长"
D.Strings[208707]="通缉：无名君王"
D.Strings[208708]="冰封之王"
D.Strings[208709]="通缉：迷失者提普托格"
D.Strings[208710]="懸賞：『屠夫』漢尼乏"
D.Strings[208711]="通缉：不朽者埃格尔"
D.Strings[208712]="通缉：噬人黑暗"
D.Strings[208713]="通缉：泰莉西亚"
D.Strings[208714]="懸賞：佩瑞斯"
D.Strings[208715]="收集50份魔血。"
D.Strings[208716]="获得30份萨格拉斯之血。"
D.Strings[208717]="在普通或更高难度的翡翠梦魇中收集30份堕落精华。"
D.Strings[208718]="在普通或更高难度的暗夜要塞中收集20个暗夜碎片。"
D.Strings[208719]="為Snicarus Dungleflight收集6根脫換的羽毛。"
D.Strings[208720]="从时空防御者身上收集4份抗迁跃镀层。"
D.Strings[208721]="是时候把我们的计划付诸实施了。\n\n欧库勒斯将把你、阿鲁因还有我一起送入魔法回廊。进入后，我们需要在夜流水渠制造一场法力风暴。\n\n瓦尔托伊将会留这里，让沙尔艾兰做好准备，迎接如潮的奥术能量——希望这足以让阿坎多尔满意。\n\n$N……我们这儿有句老话……“领袖总是孤独的”。这句话的意思是，只有那些背负领导重担的人，才会真正懂得这种责任。\n\n感谢你与我同行。其实，我觉得不孤独了。"
D.Strings[208722]="骑乘苏伊什并击败1个敌人。"
D.Strings[208723]="華爾拉亞的戰鬥領主。"
D.Strings[208724]="向魔网能量注入远古魔力。"
D.Strings[208725]="保护魔网能量并注入远古魔力。"
D.Strings[208726]="找到破损的魔力圆盘并修复魔网能量。"
D.Strings[208727]="收集6块魔网能量碎片，并向魔网能量注入远古魔力。"
D.Strings[208728]="通缉：沃洛伦船长"
D.Strings[208729]="懸賞：法斯納"
D.Strings[208730]="通缉：屠夫汉瓦尔"
D.Strings[208731]="懸賞：無名之王"
D.Strings[208732]="懸賞：『失落者』提塔格"
D.Strings[208733]="通缉：皮里克斯"
D.Strings[208734]="魔法回廊：阻塞的排水管"
D.Strings[208735]="魔法回廊：白银之蛇"
D.Strings[208736]="魔法回廊：奥术师的陨落"
D.Strings[208737]="魔法回廊：疑云密布"
D.Strings[208738]="保护预言者努波顿，抵御燃烧军团的袭击。"
D.Strings[208739]="黑鸦堡垒：……还牙！"
D.Strings[208740]="黑鸦堡垒：疯狂的奥术师"
D.Strings[208741]="神圣之骨"
D.Strings[208742]="幽暗海滩"
D.Strings[208743]="捕杀风暴"
D.Strings[208744]="暗礁在哪儿呢？"
D.Strings[208745]="黑鸦堡垒：叛徒的灭亡"
D.Strings[208746]="战地配给"
D.Strings[208747]="如此梦魇"
D.Strings[208748]="缓解疼痛"
D.Strings[208749]="巨型鱼人问题"
D.Strings[208750]="使用远古魔力，重新启动传送道标。"
D.Strings[208751]="进入大步道，消灭15个卫兵。"
D.Strings[208752]="秘密勾结"
D.Strings[208753]="凡图斯工艺"
D.Strings[208754]="你真是善于学习啊，战争领主 $n。元素们与你进行了沟通——这种沟通在这个世界中可不常见。$b$b一个真正的萨满必须踏上多条道路。而在扮演每一种角色时，你都需要称手的工具。只有最为强大的武器才能带领我们战胜燃烧军团。也许，我们应该再寻找一把强大的武器。$b$b我们应该谈一谈，然后告诉我你的选择。"
D.Strings[208755]="你真是善于学习啊，大领主 $n。元素们与你进行了沟通——这种沟通在这个世界中可不常见。$b$b一个真正的萨满必须踏上多条道路。而在扮演每一种角色时，你都需要称手的工具。只有最为强大的武器才能带领我们战胜燃烧军团。也许，我们应该再寻找一把强大的武器。$b$b我们应该谈一谈，然后告诉我你的选择。"
