D.Strings[208759]="你真是善于学习啊，死亡领主 $n。元素们与你进行了沟通——这种沟通在这个世界中可不常见。$b$b一个真正的萨满必须踏上多条道路。而在扮演每一种角色时，你都需要称手的工具。只有最为强大的武器才能带领我们战胜燃烧军团。也许，我们应该再寻找一把强大的武器。$b$b我们应该谈一谈，然后告诉我你的选择。"
