D.Strings[208766]="海盗吸血鬼！"
D.Strings[208767]="酒坊"
D.Strings[208768]="战争领主$n，谢谢你能赶过来。我有一件急事需要借助你独一无二的能力。$B$B根据白银之手的报告，邪能风暴中出现了一个非同寻常的发光物体，目前正朝着苏拉玛海岸的方向坠落。我对这件事最感到好奇的是，它在邪能风暴之中切开了一条光带。$B$B你可以去调查一下吗？克拉苏斯平台那里有一只狮鹫在等着你。"
