D.Strings[208802]="战争领主，你见过萨满阿格娜了吗？她出生在外域这个破碎的世界，并从那里的玛格汉兽人处学会了元素之道。在大灾变的前夕，她亲自帮助萨尔完成了萨满训练。年轻的新兵们能有她作为导师真是太幸运了。$b$b如果你想找到第二件神器，阿格娜一定能帮到你。她正在我们上方的风暴之眼瞭望台训练新兵。"
