D.Strings[208814]="阿格娜兰，大家叫她阿格娜。"
D.Strings[208815]="在逆风小径关闭4个传送门，消灭20个恶魔。"
D.Strings[208816]="魔法已经钳制精灵太久了。它造就了我们，让我们摆脱蒙昧——但失去平衡的魔法也会毁了我们。$B$B夏多雷太过骄傲，不愿承认这一点。他们就是放纵魔瘾的产物。他们的生活极其不和谐。$B$B但我感觉到了堕夜精灵的潜力。失去一切令他们变得谦卑。这也让他们更加坚强。$B$B坚持下去，$N。帮助堕夜精灵崛起吧。"
