D.Strings[208827]="去达拉然找这个人类女子吧。"
D.Strings[208828]="从3个远古魔力节点进行采集。"
D.Strings[208829]="蹂躏之梦"
D.Strings[208830]="海拉加尔登陆战：远石海滩"
D.Strings[208831]="光靠军队冲锋陷阵是赢不了战争的，战争领主。$b$b有时候，由单人执行的、默默无闻的战斗才是最重要的。所以说——$b$b<卡德加微微皱了皱眉。>$b$b我们还是到更隐蔽的地方讨论这件事比较好。我们去上面的紫色天台吧，怎么样？"
D.Strings[208832]="光靠军队冲锋陷阵是赢不了战争的，大领主。$b$b有时候，由单人执行的、默默无闻的战斗才是最重要的。所以说——$b$b<卡德加微微皱了皱眉。>$b$b我们还是到更隐蔽的地方讨论这件事比较好。我们去上面的紫色天台吧，怎么样？"
