D.Strings[208843]="在紫色天台与六人议会会合。"
D.Strings[208844]="在托里姆峰复活4只死去的托林尼尔幼龙。"
D.Strings[208845]="他想碾碎起义军。"
D.Strings[208846]="雷霆图腾大扫除"
D.Strings[208847]="在瓦尔莎拉的黑鸦堡垒击败20个拉文凯斯的士兵。"
D.Strings[208848]="在瓦尔莎拉的黑鸦堡垒找到3个武器箱。"
D.Strings[208849]="从瓦尔莎拉的黑鸦堡垒获得5本战术论。"
D.Strings[208850]="为塞达斯获取充能的塑魔法杖和不稳定的构造体核心。"
D.Strings[208851]="使用魔力消除器击败塑魔者索伦迪斯。"
D.Strings[208852]="破坏4个传送水晶。"
D.Strings[208853]="消灭监督者英格拉。"
D.Strings[208854]="击败魔导师之臂。"
D.Strings[208855]="肃清道路"
D.Strings[208856]="机不可失"
D.Strings[208857]="我的部队纪律严明，没有我的命令，绝对不会与辛多雷开战。$b$b可是，我不得不羞愧地承认，两支军队都在搞恶作剧，互相骚扰，还把带有侮辱含义的物品丢到对方的营地。$b$b请你帮个忙，$N，我们需要找个双方军队都尊敬的人，把这些物品收起来，以免双方擦枪走火。"
D.Strings[208858]="我的部队纪律严明，没有我的命令，绝对不会与卡多雷开战。$b$b可是，我不得不羞愧地承认，两支军队都在搞恶作剧，互相骚扰，还把带有侮辱含义的物品丢到对方的营地。$b$b请你帮个忙，$N，我们需要找个双方军队都尊敬的人，把这些物品收起来，以免双方擦枪走火。"
D.Strings[208859]="在沙尔艾兰与奥术师瓦尔托伊谈一谈。"
D.Strings[208860]="与欧库勒斯谈一谈，然后传送到阿苏纳。"
D.Strings[208861]="协助奥术师瓦尔托伊放置魔网共振器。"
D.Strings[208862]="在奥术师瓦尔托伊进行仪式期间保护她。"
D.Strings[208863]="与丝黛拉苟萨交谈并飞回沙尔艾兰。"
D.Strings[208864]="消灭15个军团入侵者。"
D.Strings[208865]="从燃烧平原上的兽人和食人魔身上收集30把斧刃。集齐后返回凿握据点向胡德鲁克复命。"
D.Strings[208866]="解除5名夜之子渗透者的伪装。"
D.Strings[208867]="为棘须船长收集100条染血的迪菲亚头巾。"
D.Strings[208868]="暗夜要塞：双头怪进门"
D.Strings[208869]="暗夜要塞：鎏金守护者"
D.Strings[208870]="暗夜要塞：补给线"
D.Strings[208871]="暗夜要塞：聚焦能量"
D.Strings[208872]="暗夜要塞：毁灭之种"
D.Strings[208873]="海边最狂暴的龙虾人。"
D.Strings[208874]="啾！啾！"
D.Strings[208875]="迅疾如風"
D.Strings[208876]="拯救诺瑞莎。"
D.Strings[208877]="前往深红林地的邪脉岗哨，消灭8个邪脉部队成员，以及他们的首领瓦提斯·阿玛兰。"
D.Strings[208878]="前往欧库勒斯的测试间收集传送笔记和1个废弃的宝珠。"
D.Strings[208879]="烧毁8份黑帆宝藏。"
D.Strings[208880]="从破碎群岛的恶魔身上收集10份魔血。"
D.Strings[208881]="在启迪平台检查4个暮色卫队占卜宝珠。"
D.Strings[208882]="时候就要到了，$N。我们的部队新增了这些龙之后，就做好了突袭破碎海滩的准备。有一支庞大的恶魔分遣队出现在了我们的一个营地附近。他们人多势众，已经令我们的盟友疲于应付了。$b$b我们这种不惧死亡，而且具有秘密武器的人正是对付这些恶魔的最佳人选，不是吗？$b$b乘上多米尔吧。我们到那儿见。"
D.Strings[208883]="将50个阿曼苏尔的精华带给奥法工匠维迪尔。"
D.Strings[208884]="消灭1个邪翼吞噬者。"
D.Strings[208885]="消灭并复活8个斯维德克维库人。"
D.Strings[208886]="战争领主，肯瑞托有办法把你传送到英灵殿，追上神王的后裔。大法师卡德加还要我对你再三强调，阻止希格林是非常重要的事，因为根据预言所示，她可能仍是联合蔑潮部族对抗军团的关键。\n\n要把你直接传送进英灵殿的话，需要花费难以置信的巨大能量，所以去之前请确保你已经有了万全的准备。否则我们可能就要等上一段时间才能再次传送了。\n\n你准备好了的话就告诉我。"
