D.Strings[208899]="你觉得怎么样？！"
D.Strings[208900]="緩解腐化"
D.Strings[208901]="有了火药，我们也该进行下一步计划了。到破碎海滩来见我们吧。$b$b你可以从克拉苏斯平台直接飞到我们的下一个目标地点。我们到那儿见，战争领主。"
