D.Strings[208913]="消灭8个恶魔，然后登上斜坡顶部。"
D.Strings[208914]="我们到了，战争领主。这座岛上有个洞窟，里面全是极其强大的恶魔和他们的首领。如果我们的计划成功，这些恶魔就会如特塞斯所说的那样，被“炸成碎片”。$b$b现在没时间详细解释整个计划了，但是苔丝答应与你同行。首先，你必须登上这面斜坡的顶部。别忘了顺路杀几个恶魔。"
