D.Strings[208938]="在守护者圣殿里打扫出8堆奥法之尘。"
D.Strings[208939]="你准备好了吗，战争领主？我会引导你一步步完成这个计划的。所以你绝对安全！首先，看到我身后的垂降点了吗？你得从那里进入洞穴。祝你好运！"
