D.Strings[208951]="不用紧张，战争领主。如果真有人能完成这个任务，那一定是你！……大概吧。使用我身后的垂降点，进入洞窟吧。$b$b什么？别摆出那副表情。你进入洞窟后，我再给你进一步的指示。"
