D.Strings[208975]="在黑云峰击败15个恶魔。"
D.Strings[208976]="从牢笼中释放8个被俘的恐怖图腾成员。"
D.Strings[208977]="军团突袭：雷霆图腾"
D.Strings[208978]="在邪能要塞治疗8个受伤的萨满。"
D.Strings[208979]="收集3个火焰能量核心，3个流水能量核心，3个土地能量核心和3个大气能量核心。"
D.Strings[208980]="钥匙是支柱"
D.Strings[208981]="神秘學者來襲"
D.Strings[208982]="举起武器。"
D.Strings[208983]="净化烈焰"
D.Strings[208984]="不是我们点的火"
D.Strings[208985]="古樹防衛戰"
D.Strings[208986]="使命终结"
D.Strings[208987]="不受约束的力量"
D.Strings[208988]="有鞭子的地方……"
D.Strings[208989]="地狱清道夫"
D.Strings[208990]="远古尸骸"
D.Strings[208991]="狩猎法则"
D.Strings[208992]="蝌蚪的礼物"
D.Strings[208993]="管束蛮兵"
D.Strings[208994]="突破要塞"
D.Strings[208995]="搜寻遗物"
D.Strings[208996]="获取25块魔石矿石和一颗苏拉玛蓝宝石。"
D.Strings[208997]="蜘蛛毒性"
D.Strings[208998]="超级蜘蛛"
D.Strings[208999]="通过我们在破碎群岛的战役，你已经为你的古代神器注入了能量。但随着燃烧军团的入侵加剧，我们必须尽快解锁这把武器的潜力。\n\n我们可以稍后再进行缓慢稳妥的研究。但现在，我们得加快进度了。\n\n将我们的职业大厅资源投入对武器历史的研究，我们就能加快你的神器获得能量的速度了。\n\n我们可以开始了吗，战争领主？"
