D.Strings[209011]="邪能腐化的羽毛"
D.Strings[209012]="头儿，你已经踏遍了破碎群岛的每个角落，为你的古代神器注入了许多能量。但那些恶魔是不会放弃的，我们急需解锁那把武器的更多潜力……马上就要！\n\n缓慢稳妥的研究是一回事，但今天，我们得加快速度了。\n\n我们这么办。你把职业大厅的资源交给我，我就能研究那把武器的历史，帮你找出增加神器能量的方法。\n\n你觉得这买卖怎么样，战争领主？"
