D.Strings[209024]="你真是破碎群岛的灾星，从我们的敌人那里夺取了大量能量灌注进你的古代神器里。但我们决不能自满，还得进一步解锁你那把武器的潜力！\n\n我们可以稍后再进行缓慢稳妥的研究。但现在，我们必须加快进度了。\n\n将我们的职业大厅资源投入对武器历史的研究，我们就能加快你的神器获得能量的速度了。而力量总是令人陶醉。\n\n我们可以开始了吗，战争领主？"
