D.Strings[209036]="通过我们在破碎群岛的战役，你已经为你的古代神器注入了能量。但随着燃烧军团的入侵加剧，显然我们必须尽快解锁你这把武器的潜力。\n\n我们可以稍后再进行缓慢稳妥的研究。但现在，我们得加快进度了。\n\n将我们的职业大厅资源投入对武器历史的研究，我们就能加快你的神器获得能量的速度了。\n\n我们开始吧，战争领主！"
