D.Strings[209072]="你在破碎群岛迎头痛击了一个又一个敌人，为你的古代神器注入了能量。但燃烧军团毫无荣誉可言，为了击败他们，我们必须尽快解锁你这把武器的潜力。\n\n我们可以稍后再进行缓慢稳妥的研究。但现在，我们得加快向胜利迈进的步伐了。\n\n将我们的职业大厅资源投入对武器历史的研究，我们就能加快你的神器获得能量的速度了。\n\n荣耀在等着我们，战争领主。"
