D.Strings[209117]="邪能风暴一直源源不断地将恶魔渣滓输送到海滩上。基尔加丹相信，他的大军无穷无尽，他的资源永不枯竭。\n\n我们要让他看看，他错得有多么离谱。\n\n冲进他们的阵地里去当中大杀四方吧，战争领主。斩杀一只又一只的恶魔，让恶魔的鲜血浸透你的双手。让他们哭喊着求你饶命，让他们尖叫着滚回扭曲虚空。"
