D.Strings[209129]="虽然我们正在尽力从军团手中收复破碎海滩，但也不能让破碎群岛的其他地方落入军团的魔掌。\n\n基尔加丹已经向破碎群岛各处派出了部队，威胁着你的新盟友的家园。在这个危急时刻，你必须回应他们的呼唤。\n\n请迅速击退这些恶魔的突袭，战争领主。抗魔联军会牢牢守住破碎海滩的。"
