D.Strings[209151]="你的组织作出了卓越贡献，大德鲁伊。你的勇士们也多次成功击退了军团的入侵。\n\n在我们为突袭萨格拉斯之墓做准备期间，也不能让恶魔站稳脚跟。我们要在所有战场上打击他们的气焰，我们还要寻找他们的弱点并加以利用。\n\n派出你们组织的勇士吧，$n。他们的任务对我们这场战役的成败至关重要……尤其是在我们即将直面基尔加丹的关键时刻。"
D.Strings[209152]="你的组织作出了卓越贡献，屠魔者。你的勇士们也多次成功击退了军团的入侵。\n\n在我们为突袭萨格拉斯之墓做准备期间，也不能让恶魔站稳脚跟。我们要在所有战场上打击他们的气焰，我们还要寻找他们的弱点并加以利用。\n\n派出你们组织的勇士吧，$n。他们的任务对我们这场战役的成败至关重要……尤其是在我们即将直面基尔加丹的关键时刻。"
D.Strings[209153]="在破碎海滩收集2500块虚空碎片。"
D.Strings[209154]="你肯定注意到了，恶魔死后会留下一些虚空碎片，那是扭曲虚空的能量结晶。我正在进行的实验需要大量的这种碎片……确切来说，是2500块。$b$b你干嘛要用那种眼神看着我？我们早就讨论过了吧，我仔细算过的。$b$b我需要的，不多不少，就是2500块碎片。少了不够，多了不行。$b$b不要质疑我的算法。快去吧！"
