D.Strings[209208]="收集50个森提纳克斯号印记。"
D.Strings[209209]="纳拉索斯虽然只是个半神，但他的气息依然萦绕在玛凯雷的黑暗角落。"
D.Strings[209210]="\"$N,\n\n我们已经赢得许多对抗燃烧军团的战斗，但这一次我们要彻底终结这场战争。\n\n最后的准备工作已经就绪，准备向阿古斯出发。\n\n快点赶去暴风城港口。那里有艘船正在等着你，将会把你和你的盟友带往秘蓝岛。\""
D.Strings[209211]="进入光铸炮台并杀死30个疯狂的灾翼蝠。"
D.Strings[209212]="在破碎之野消灭20个攻击者。"
D.Strings[209213]="幽魂起义"
D.Strings[209214]="摧毁3个军团灭绝者。"
D.Strings[209215]="为格里伏塔收集9999枚空气硬币。"
D.Strings[209216]="我们的部队在守卫维迪卡尔的时候承受了巨大的损失，$n。我们需要盟友的支援。$B$B圣光军团以吸收燃烧远征的幸存者，充实自己的力量而著称。我们也必须这么做。$B$B我感到附近有你释放的燃烧军团的奴隶。我猜他们已经开始对抗自己的主人。$B$B如果你能和我一起前去寻找就太好了，$N。"
D.Strings[209217]="阿克蒙德并不知道自己会成为污染者，但他对力量的追求也不是从萨格拉斯出现时才开始的。"
D.Strings[209218]="永恒复仇"
D.Strings[209219]="把50个沸腾的精华带给奥法工匠维迪尔。"
D.Strings[209220]="\"$N,\n\n我们已经赢得了许多对抗燃烧军团的战斗，但这一次我们要彻底终结这场战争。\n\n最后的准备工作已经准备就绪，准备向阿古斯出发。\n\n快点赶去刃拳海湾。那里有艘船正在等着你，将会把你和你的盟友带往秘蓝岛。\""
D.Strings[209221]="作为基尔加丹手下的秘密狩猎大师，塔尔加斯一直在群星间追杀着德莱尼。"
D.Strings[209222]="将3头野生岩羊带给首席骑兵贾伊德。"
D.Strings[209223]="使用先知护符，净化9名阵亡的圣光军团战士。"
D.Strings[209224]="前往石化森林，回收12个用过的瓶子。"
D.Strings[209225]="消灭安尼赫兰熔池的14头邪焰清道夫。"
D.Strings[209226]="把75株星辰之耀，5个源生萨格里特以及一枚地狱火炼金石交给弗恩。"
D.Strings[209227]="收集恶魔皮革和光纹布，然后使用恩斯特拉的制革油制作12块净化的恶魔皮革。"
