D.Strings[209252]="小牙"
D.Strings[209253]="收集3份圣光残迹。"
D.Strings[209254]="将50个觉醒精华带给奥法工匠维迪尔。"
D.Strings[209255]="我花了好几个星期到处逃跑，因为害怕黑骑士追杀，所以我从不敢在一个地方逗留太长的时间。我现在躲在乌鸦岭的一座废弃的小镇里，和平常一样东躲西藏。我不敢面对他们杀死斯温妻子时所用的那种未知魔法，而且我知道他们还在暮色森林中搜寻镰刀。让我感到庆幸的是，它已经不在我手里了，否则的话我肯定会被他们发现。即使是现在，我也知道自己终究会被别人发现。$B$B 我实在是太累了。"
D.Strings[209256]="艾尔加丁爵士来自人类的贵族家庭。他的父亲艾尔加丁伯爵以慷慨大方而着称。第二次兽人战争之后，正是因为他父亲的游说和疏通，石匠公会才在重建暴风城时获得了更好的工作条件。"
D.Strings[209257]="接下来的几年，在暴风城背叛了石匠公会后，艾尔加丁爵士开始厌恶他的贵族身份。他不愿因继承了他父亲的高贵血统而在贵族中获得崇高的地位。不过我离题了。这个故事的主题不是政治文章或者人物传记，而是要叙述我在荆棘谷的青山中猎捕的经历。"
D.Strings[209258]="正在我准备问艾耶克为什么一整天都无精打采的时候，她突然从箭囊中抽出一支箭，向可怜的巴尼尔射去——当然她的目标并非巴尼尔。瞠目结舌的巴尼尔向后退了几步，看着自己身后的一只巨大的鳄鱼浮出水面，艾耶克的箭正好射在了它的两只眼睛的中间。"
D.Strings[209259]="艾尔加丁爵士似乎被绊了一下，将手重重地拍在巴尼尔的肩膀上。我和艾耶克瞥了一眼，以为他会责备粗心大意的巴尼尔。然而艾尔加丁爵士却摆了摆头，示意我们观察旁边的一棵倒下的大树。那里正有一双炯炯有神的黑眼睛瞪着我们，眼睛下面还有一口如剃刀般锋利的牙齿。"
D.Strings[209260]="这次成功的猎杀给探险队带来了一些愉快的心情，巴尼尔给大家倒了些蜜酒，但是这种喜悦只是暂时的。当我们准备把尸体运回营地时，丛林里传来了一阵可怕的嚎叫声。在我的一生中，我从来都没有听到过如此可怕的、几乎让人全身血液都凝固的声音。"
D.Strings[209261]="在遍布岩石的悬崖上，一头迄今为止我见过的最巨大的豹子在晚霞的映衬中冒了出来。我笨拙地开了枪，但是那头豹子丝毫未动。它又咆哮了一声，比第一次的声音更大，然后就消失了。$B$B 我们把东西收好，然后神色黯然地返回了营地。"
D.Strings[209262]="我向探险队员保证我们第二天将去狩猎黑豹，因为整个艾泽拉斯地区的豹皮都非常抢手而紧俏。正是因为有这种需求的存在，才有那么多的猎人、捕兽者和毛皮商人以联盟的名义勇敢地献出了他们的生命。"
D.Strings[209263]="这一天，我们沿着一些新的黑豹足迹向南进发。很快我们就来到了一座架着巨大索桥的峡谷。看到这个工程奇迹的时候，我忍不住想起了布莱恩对这一带的描写。我们常常认为食人妖是原始而无知的族类，然而当我认识到这座索桥所体现的精湛技术时，我开始认为食人妖的建造技术已经达到令人难以想像的地步。"
D.Strings[209264]="很快亚捷就发现在西南方有猎豹出现。我们紧握住手中的枪，悄无声息地前进，随时准备对付突然冒出来的猎物。附近树丛里发出的树枝断裂的劈啪声立刻引起了我们注意，那里一定有什么东西！我瞥了巴尼尔一眼，他就明白了我的意思。这个猎物不是我们的，而是留给我们的人类同伴的。已经有无数猎豹死在我们的枪管下，这一次轮到人类伙伴们开开杀戒了。"
D.Strings[209265]="亚捷和艾尔加丁爵士悄无声息地用枪瞄准着正在晃动的树丛。正午的强烈阳光照在我们身上，当艾尔加丁爵士终于扣动扳机的时候，他的额头流下了一丝汗水。一声枪响过后，浓密的树叶被打得乱飞，一头非常漂亮的大黑豹向离弦的箭一般冲向了平原。"
D.Strings[209266]="当黑豹沿着林木边缘奔走时，有两个猎人一直瞄准着它。他们互相照应着一起行动，巴尼尔看看我，用眼光询问是否要开火，我摇了摇头。这次狩猎行动是要锻炼那些人类，而不是我或者巴尼尔。艾尔加丁扣动了扳机，但没能打中黑豹。显然，他对猎枪所产生的强大后坐力还没有足够的认识和准备。"
D.Strings[209267]="他的枪重重地击在他的肩膀上，枪管歪向一边，正好落在在艾耶克的枪下面。艾耶克瞄准树冠适时地扣动了扳机，一声清晰的枪响过后，树冠上的一群鸟尖叫着四处飞散，树上冒出了一阵烟，我们惊异地看到一根巨大的树枝掉落下来，正好砸中了疾驰的黑豹。"
D.Strings[209268]="我曾经在战场上面对过巨大的地狱火，还有从四面八方冲过来的燃烧军团。如今对我而言，一群蛮横的食人妖就跟丹莫洛的长耳大野兔一样不值一提。$B$B 我们平静地穿过伽什废墟，巴尼尔总算是放下了他那颗惴惴不安的心。我们继续向西边的无尽之海前进，并绕了南边的祖昆达废墟。当我们攀上海边的悬崖之后，第一只迅猛龙出现在我们面前。"
D.Strings[209269]="这头野兽压根没有发现我们的存在，事实上，它从我们这儿收到的第一个问候就是射入它双眼间的子弹。$B$B 艾尔加丁爵士大声欢呼，艾耶克则赞许地向我点了点头。我从包里拿出烟斗，想好好庆祝一番。巴尼尔奔上山坡去拖迅猛龙的尸体。我看着被击倒的野兽，心里就像以前每一次杀死猎物时那样充满着兴奋和满足。"
D.Strings[209270]="我举着枪缓缓地前进。是我将这些勇敢的猎人带向了死亡的边缘，我至死都要保护他们！鞭尾迅猛龙异常凶残，它们一向都以残酷嗜血而闻名，而且现在它们的数量远远多于我们。但是，我决不能就让这些野兽轻易地杀了我和我的同伴。"
D.Strings[209271]="艾耶克和艾尔加丁爵士拿起他们的武器，守在我的两侧，我们的背后就是大海。巴尼尔沮丧地叹了一口长气，然后拿起了他的斧头。迅猛龙在慢慢地逼近，它们高傲地注视着我们，因为它们知道我们已经无路可逃了。"
D.Strings[209272]="在搜集苔藓标本的时候，我经历了一场血腥的战斗。邪鳍部族的鱼人遭到了一群豺狼人的袭击，战场上留下了无数鱼人和豺狼人的尸体。我注意到某个鱼人的伤口上长着一个坚硬的肿瘤。仔细观察这个肿瘤之后，我发现它和我收集的苔藓的特性差不多。不幸的是，除了这具尸体之外，我在别的尸体上找不到类似的肿瘤了。"
D.Strings[209273]="同时，我还派出了阿维罗德上尉在卡利姆多大陆执行侦察任务。他的部队完成任务之后会与我们在提拉加德城堡的部队会合。$B$B 阿维罗德上尉的任务可能需要很长时间，因为这片新大陆幅员辽阔、充满危机。如果我或者本尼迪克遭遇不幸的话，阿维罗德将接手城堡的指挥权。$B$B 我们会发动一轮接一轮的攻击，直到占领这座要塞!$B$B - 普劳德摩尔上将"
D.Strings[209274]="风险投资公司的函件在矿坑的外面……可能在底层的什么箱子里。$B$B祝你好运，记住……$B$B蓝色炸药：伐木场$B红色炸药：矿坑$B$B哦，完成任务之后别忘了把信也毁了。嗯，也许我该想个办法让这些东西在被人读过之后就自我销毁，这个主意不错……"
D.Strings[209275]="对我们地鼠有限公司来说，最让我们伤心的是，我们收到报告说有一些贪婪的蓝叶薯猎人不顾自己宠物的安全，把它们送入危险的地方搜寻蓝叶薯。$B$B 我们决不能宽恕这样的行为，但是为了保证顾客对我们售出的每一只地鼠满意，我们郑重承诺：所有购买本公司产品的顾客都可以拿着购买凭证随时领取新的地鼠。$B$B 祝您狩猎愉快!"
D.Strings[209276]="我们会使用和往常一样的管道来完成支付。顺及，请给这位信差支付一份标准的报酬，您可以把它算进盾牌的价格中。$B$B $B$B 非常感谢！$B 您真诚的格林戈·雷矛"
D.Strings[209277]="我真希望再也没有其他的达拉然法师召唤狼人了——即使是出于良好的目的。只要不再签订更多的契约，就不会有更多的秘密被泄露出去，这些野兽是不会为我们带来任何好处的。$B$B它们最好永远留在它们的世界里。如果它们来到我们的世界，那我们无疑将面临毁灭的劫难……"
D.Strings[209278]="显然，正是克拉文锁在箱子中的东西对塔中的居民产生了有害的影响。我猜测其他的守卫体内也应该有着同样的恶臭，而且，有可能连克拉文自己也已经成了这种影响的牺牲品。$B$B 密探安玻·吉尔妮$B 军情七处 国内行动八组"
D.Strings[209279]="更多引用!$B$B“完成某件超强的发明并亲身感受它的力量，你知道这样的感觉是多么美妙吗?地精可不知道。”$B-- 尼克斯·斯普克斯宾，加基森高级技师$B$B“工程学就是让幻想变得更加奇妙的东西!”$B-- 洛维斯，地精发明家"
D.Strings[209280]="任何一个有智慧的生物找到这张便笺的时候，他们都一定会自问道：“为什么他们会去招惹具有暴力倾向的30尺高的巨人呢?”$B$B -- 穆克"
D.Strings[209281]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\"><BR/> 西部水晶塔图表<BR/> </H1><BR/> <BR/><BR/> <IMG src=\"InterfacePictures11482_crystals_west\"/><BR/> </BODY><BR/> </HTML>"
D.Strings[209282]="在确认永恒之井就是使恶魔进入这个世界的大门之后，玛法里奥坚持认为应该摧毁它。他的同伴们被他这个疯狂的想法吓呆了——永恒之井是他们长寿和力量的源泉。但是泰兰德知道这是一个明智的抉择，于是她请求塞纳留斯和巨龙摧毁艾萨拉的神殿，并找到关闭永恒之井传送门的方法。"
D.Strings[209283]="克尔苏加德领导的信徒急切地希望死去并为他们的主人服务，他们希望通过这种方式变成不死之身。随着瘟疫逐渐扩散，洛丹伦北部出现了越来越多的僵尸，克尔苏加德管理着这支日益庞大的部队，并称他们为“天灾”——不久之后，它就会踏进洛丹伦的大门，并把人类从这个世界上永远抹掉。"
D.Strings[209284]="内战后幸存的古拉巴什部族继续留在他们那已成为一片废墟的家园里，但是却走上了不同的路，劈颅部族、血顶部族和暗矛部族开始在荆棘谷争抢丛林领地。虽然他们最终达成了脆弱的和平，但仍有预言说哈卡将会在未来的某日在这个世界上重生，到那时，他将毁灭一切。"
D.Strings[209285]="塞纳留斯告诉大地的孩子如何与树林进行沟通。舒哈鲁成了德鲁伊，他们使用各种魔法来呵护这片土地的健康。塞纳留斯和数代舒哈鲁一起狩猎，共同保护这片土地免受潜伏在地下的邪恶力量的伤害。"
D.Strings[209286]="现代习俗$B$B其他文明开始意识到冬幕节是一个欢庆的节日，虽然一些传统和传说中的并不完全一致。通常，人们可不会顾及太多关于节日本身的来历，他们所关心的只是在这个节日期间可以好好庆祝并交换礼物，这就是冬幕节现在的习俗。现在冬天爷爷的形象也广泛用在商业用途，而不是表现为一个超自然的泰坦巨人。"
D.Strings[209287]="艾尔加丁爵士来自人类的贵族家庭。他的父亲艾尔加丁伯爵以慷慨大方而着称。第二次兽人战争之後，正是因为他父亲的游说和疏通，石匠公会才在重建暴风城时获得了更好的工作条件。"
D.Strings[209288]="正在我准备问艾耶克为什麽一整天都无精打采的时候，她突然从箭囊中抽出一支箭，向可怜的巴尼尔射去─当然她的目标并非巴尼尔。瞠目结舌的巴尼尔向後退了几步，看着自己身後的一只巨大的鳄鱼浮出水面，艾耶克的箭正好射在了它的两只眼睛的中间。"
D.Strings[209289]="这次成功的猎杀给探险队带来了一些愉快的心情，巴尼尔给大家倒了些蜜酒，但是这种喜悦只是暂时的。当我们准备把屍体运回营地时，丛林里传来了一阵可怕的嚎叫声。在我的一生中，我从来都没有听到过如此可怕的、几乎让人全身血液都凝固的声音。"
D.Strings[209290]="在遍布岩石的悬崖上，一只迄今为止我见过的最巨大的猎豹在晚霞的映衬中冒了出来。我笨拙地开了枪，但是那只豹丝毫未动。它又咆哮了一声，比第一次的声音更大，然後就消失了。$B$B我们把东西收好，然後神色黯然地返回了营地。"
D.Strings[209291]="我向探险队员保证我们第二天将去狩猎黑豹，因为整个艾泽拉斯地区的豹皮都非常抢手而紧俏。正是因为有这种需求的存在，才有那麽多的猎人、陷捕者和毛皮商人以联盟的名义勇敢地献出了他们的生命。"
D.Strings[209292]="这一天，我们沿着一些新的黑豹足迹向南进发。很快我们就来到了一座架着巨大索桥的峡谷。看到这个工程奇蹟的时候，我忍不住想起了布莱恩对这一带的描写。我们常常认为食人妖是原始而无知的族类，然而当我认识到这座索桥所体现的精湛技术时，我开始认为食人妖的建造技术已经达到令人难以想像的地步。"
D.Strings[209293]="不久前，艾耶克追踪猎豹到西南方。我们静静地走着，枪支随侍在旁，等待猎物出现。附近的杂树林一发出嫩枝劈啪声，立刻就吸引了我们的注意力。严肃地看巴尼尔一眼，就足以表达我的想法。巴尼尔慢慢地压低他的来福枪。这不是我们自己的猎杀;是为了我们的人类同胞。无数只猎豹在我们冒烟的枪管下丧命。这次的猎杀是属於人类的。"
D.Strings[209294]="艾耶克和艾尔加丁爵士悄无声息地用枪瞄准着正在晃动的树丛。正午的强烈阳光照在我们身上，当艾尔加丁爵士终於扣动扳机的时候，他的额头流下了一丝汗水。一声枪响过後，浓密的树叶被打得乱飞，一只非常漂亮的大黑豹向离弦的箭一般冲向了平原。"
D.Strings[209295]="当黑豹沿着林木边缘奔走时，有两个猎人一直瞄准着它。他们互相照应着一起行动，巴尼尔看看我，用眼光询问是否要开火，我摇了摇头。这次狩猎行动是要锻炼那些人类，而不是我或者巴尼尔。艾尔加丁扣动了扳机，但没能打中黑豹。显然，他对猎枪所产生的强大後座力还没有足够的认识和准备。"
D.Strings[209296]="我曾经在战场上面对过巨大的炼狱火，还有从四面八方冲过来的燃烧军团。如今对我而言，一群蛮横的食人妖就跟丹莫洛的长耳大野兔一样不值一提。$B$B我们平静地穿过伽什废墟，巴尼尔总算是放下了他那颗惴惴不安的心。我们继续向西边的无尽之海前进，并绕了南边的祖昆达废墟。当我们攀上海边的悬崖之後，第一只迅猛龙出现在我们面前。"
D.Strings[209297]="这头野兽压根没有发现我们的存在，事实上，它从我们这儿收到的第一个问候就是射入它双眼间的子弹。$B$B艾尔加丁爵士大声欢呼，艾耶克则赞许地向我点了点头。我从包里拿出烟斗，想好好庆祝一番。巴尼尔奔上山坡去拖迅猛龙的屍体。我看着被击倒的野兽，心里就像以前每一次杀死猎物时那样充满着兴奋和满足。"
D.Strings[209298]="我们匆忙射出的子弹为巴尼尔赢得了足够的逃跑时间。他大声叫嚷着跑下山丘，重新回到队伍之中。我们急忙离开了丛林，因为有一群凶残的鞭尾迅猛龙正在追寻着我们的足迹。$B$B现在攻守易位，猎手变成了猎物。"
D.Strings[209299]="我慢慢地向前走，高举我的枪。我已让这些勇敢的猎人走向死亡。我死也要保卫他们。鞭尾迅猛龙特别凶猛，牠们无情的嗜血性是出名的。牠们的数量远远超过我们。但我如果没有先让牠们洒几滴血就让牠们杀了我和同伴，那我会下地狱的。"
D.Strings[209300]="艾耶克和艾尔加丁爵士拿起他们的武器，守在我的两侧，我们的背後就是大海。巴尼尔沮丧地叹了一口长气，然後拿起了他的斧头。迅猛龙在慢慢地逼近，它们高傲地注视着我们，因为它们知道我们已经无路可逃了。"
D.Strings[209301]="聪明的月亮与伟大的雄鹿做了笔交易——如果他爱她，并能够为她结束孤独的生活，她就可以解救他。$B$B 姆沙爱着阿帕罗，并为他生下了一个孩子。这个孩子作为半神降生于夜晚的森林中。他被起名为塞纳留斯，他漫步于正在觉醒的世界和天堂王国之间，漫步在布满星辰的大道上。"
D.Strings[209302]="舒哈鲁被迫离开自己祖居的地方，从此之后不得不像游牧民族一样浪迹在无边的平原上。这种情况一直在继续下去——破碎的舒哈鲁族部族希望他们能在大地之母的指引下找到一处新的家园。"
